  const database = await openDatabase()
  let stored = await get(database)
  if (!stored) {
    const generated = await crypto.subtle.generateKey(
      { name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"],
    )
    if (!("privateKey" in generated)) throw new Error("device key-pair generation failed")
    const publicKey = new Uint8Array(await crypto.subtle.exportKey("spki", generated.publicKey))
    const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", publicKey))
    stored = { deviceId: `web-${hex(digest.slice(0, 12))}`, keyPair: generated }
    await put(database, stored)
  }
  const identity = stored
  const publicKey = new Uint8Array(await crypto.subtle.exportKey("spki", identity.keyPair.publicKey))
  return {
    deviceId: identity.deviceId,
    publicKey,
    sign: async challenge => new Uint8Array(await crypto.subtle.sign(
      { name: "ECDSA", hash: "SHA-256" }, identity.keyPair.privateKey, challenge,
    )),
  }
}
